const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',book:'<path d="M12 5v16M3 3c4-1 7 0 9 2 2-2 5-3 9-2v16c-4-1-7 0-9 2-2-2-5-3-9-2z"/>',moon:'<path d="M21 13A9 9 0 0 1 11 3a9 9 0 1 0 10 10Z"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',search:'<circle cx="10.5" cy="10.5" r="7.5"/><path d="m16 16 5 5"/>',play:'<path d="m8 4 12 8-12 8z" fill="currentColor" stroke="none"/>',pause:'<path d="M7 5v14M17 5v14" stroke-width="5"/>',sprout:'<path d="M12 22v-9C4 14 2 8 3 5c7-1 10 3 9 8 0-7 3-10 10-10 0 7-3 11-10 10"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>',back:'<path d="M4 9a8 8 0 1 1 0 7M4 3v6h6"/>',next:'<path d="M20 9a8 8 0 1 0 0 7m0-13v6h-6"/>',volume:'<path d="m11 4-6 5H2v6h3l6 5zM15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',expand:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',star:'<path d="m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z"/>',leaf:'<path d="M20 3C5 2 1 10 6 16s16 0 14-13ZM4 21 15 9"/>',check:'<path d="m5 12 4 4L19 6"/>'};
icons.map='<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3zM9 3v15m6-12v15"/>';icons.lock='<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>';icons.trophy='<path d="M8 3h8v7a4 4 0 0 1-8 0zM8 5H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4M12 14v6m-4 1h8"/>';
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.star}</svg>`;
const stories=[{id:'noah',title:'Uma arca cheia de amor',subtitle:'Noé e a promessa de Deus',image:'noah-ark',category:'Aventuras',tag:'Para se encantar',age:'3–8 anos',ref:'Gênesis 6–9',description:'Embarque com Noé e seus amigos animais em uma aventura sobre confiança, cuidado e uma promessa colorida no céu.'},{id:'david',title:'Pequeno pastor, grande coração',subtitle:'Davi e o cuidado de Deus',image:'david-shepherd',category:'Coragem',tag:'Pequenos corajosos',age:'3–8 anos',ref:'1 Samuel 16 · Salmo 23',description:'Entre colinas e ovelhinhas, Davi descobre que um coração cheio de fé pode encontrar coragem nas pequenas coisas.'},{id:'night',title:'Paz no barquinho',subtitle:'Um descanso nos braços de Jesus',image:'jesus-night',category:'Para dormir',tag:'Hora de aconchegar',age:'3–8 anos',ref:'Marcos 4:35–41',description:'A noite chegou. Deixe as preocupações na margem e embarque em uma história tranquila sobre confiar no cuidado de Jesus.'}];
stories.push({id:'promise',title:'As cores de uma promessa',subtitle:'Depois da chuva, um recomeço',image:'noah-ark',category:'Aventuras',tag:'Novos começos',age:'3–8 anos',ref:'Gênesis 9:12–17',description:'Depois de uma longa chuva, um arco-íris ensina a Noé que cada novo dia pode trazer esperança.'},{id:'shepherd',title:'Você nunca está sozinho',subtitle:'O carinho do bom pastor',image:'david-shepherd',category:'Coragem',tag:'Deus cuida de mim',age:'3–8 anos',ref:'Salmo 23',description:'Uma caminhada por campos tranquilos para lembrar que somos amados e que podemos pedir ajuda.'},{id:'thanks',title:'Um céu de agradecimentos',subtitle:'Pequenas coisas, grandes presentes',image:'jesus-night',category:'Para dormir',tag:'Gratidão',age:'3–8 anos',ref:'Salmo 136:1',description:'Antes de dormir, descubra como as pequenas alegrias do dia podem se transformar em uma oração de gratidão.'});
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
let favorites=read('sementinha-favorites',[]),page='journey',filter='Todas',query='',current=stories.find(s=>s.id===read('sementinha-last','noah'))||stories[0],timer=null,timerMinutes=0,speed=1;
const audio=document.getElementById('audio');audio.src=`/assets/${current.id}.m4a`;const app=document.getElementById('app');const asset=s=>`/assets/${s.image}.jpg`;const fmt=t=>Number.isFinite(t)?`${Math.floor(t/60)}:${String(Math.floor(t%60)).padStart(2,'0')}`:'0:00';
function save(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{}}
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('visible');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>t.classList.remove('visible'),2800)}
function nav(){return `<aside class="sidebar"><div class="brand">${icon('sprout')}sementinha</div><div class="brand-sub">pequenas histórias. grande amor.</div><nav class="nav" aria-label="Navegação principal">${[['home','home','Início'],['journey','map','Jornada'],['library','book','Histórias'],['sleep','moon','Boa noite'],['favorites','heart','Favoritas']].map(([p,i,t])=>`<button data-page="${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${icon(i)}<span>${t}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="side-note">${icon('sprout')}Cada história ouvida<br>é uma sementinha de amor.</div><button class="parents" data-page="parents">${icon('shield')}Espaço dos pais</button></div></aside>`}
function card(s){return `<button class="story" data-story="${s.id}" aria-label="Ouvir ${s.title}"><div class="cover"><img src="${asset(s)}" alt="${s.subtitle}" loading="lazy"><span class="cover-tag">${isUnlocked(s.id)?s.tag:'Em breve na sua jornada'}</span><span class="cover-play">${icon(isUnlocked(s.id)?'play':'lock')}</span></div><h3>${s.title}</h3><p>${s.category} <span aria-hidden="true">·</span> ${s.age}</p></button>`}
function chips(){return `<div class="filters" role="group" aria-label="Categorias">${[['Todas','star'],['Aventuras','book'],['Coragem','sun'],['Para dormir','moon']].map(([t,i])=>`<button data-filter="${t}" class="chip ${filter===t?'active':''}" aria-pressed="${filter===t}">${icon(i)}${t==='Todas'?'Todas as histórias':t}</button>`).join('')}</div>`}
function hero(s,sleep=false){return `<section class="hero"><img class="hero-art" src="${asset(s)}" alt="${s.subtitle}"><div class="hero-copy"><div class="eyebrow">${icon(sleep?'moon':'sun')}${sleep?'Um abraço antes de dormir':'A história de hoje'}</div><h2>${s.title}</h2><p>${sleep?'Respire devagar. Jesus cuida de você, até enquanto você sonha.':'Uma aventura sobre confiar em Deus e cuidar uns dos outros.'}</p><div class="hero-bottom"><button class="primary" data-story="${s.id}">${icon('play')}${sleep?'Ouvir e descansar':'Vamos ouvir'}</button><span class="small">${s.age}</span></div></div></section>`}
function content(){if(page==='journey'&&!query)return journey();if(page==='parents')return `<div class="page-intro"><h1>Um cantinho para os pais</h1><p>Pequenos momentos de conexão, vividos em família.</p></div><section class="parent-panel"><h2>Feito para ouvir juntinhos</h2><p>A jornada abre uma nova descoberta a cada história ouvida. Os dias de escuta, as etapas e o tema escolhido ficam guardados neste navegador.</p><p>As histórias são adaptações infantis inspiradas na Bíblia. Depois de ouvir, conversem sobre o que mais tocou o coração de vocês.</p><div class="settings-row"><div><strong>Sobre os áudios</strong><small>Esta é uma versão de demonstração.</small></div>${icon('book')}</div><p>As seis histórias têm narração sintética demonstrativa. Os arquivos podem ser substituídos por gravações definitivas.</p><div class="settings-row"><div><strong>Desligar o áudio em</strong><small>Um descanso sem pressa.</small></div>${timerSelect()}</div><div class="settings-row"><div><strong>Suas histórias favoritas</strong><small>Salvas somente neste navegador.</small></div><button class="text-button" data-page="favorites">Ver ${icon('arrow')}</button></div><div class="settings-row"><div><strong>Idade sugerida</strong><small>3 a 8 anos, com acompanhamento de um adulto.</small></div>${icon('heart')}</div></section>`;
if(page==='home'&&!query&&filter==='Todas')return `<div class="heading"><div><h1>O amor cresce<br>a cada história.</h1><p>Qual aventura vamos viver juntos hoje?</p></div><span class="tiny-sun">${icon('sun')}</span></div><div class="home-feature">${hero(stories[0])}<button class="journey-invite" data-page="journey"><span class="chapter-label">Seu pequeno grande caminho</span>${icon('map')}<h2>Vamos explorar<br>o Jardim da Fé?</h2><span>${journeyCount()} de 6 descobertas ${icon('arrow')}</span></button></div>${chips()}<div class="section-head"><h2>Um mundo de histórias</h2><button class="text-button" data-page="library">Explorar todas ${icon('arrow')}</button></div><div class="cards home-cards">${stories.slice(0,3).map(card).join('')}</div><section class="night-banner"><img class="night-image" src="${asset(stories[2])}" alt="Barco tranquilo sob o céu estrelado" loading="lazy"><div class="night-copy">${icon('moon')}<h2>O dia termina. O amor fica.</h2><p>Histórias calminhas para sonhos bonitos.</p><button class="text-button" data-page="sleep">Vamos desacelerar ${icon('arrow')}</button></div></section><p class="footer-note">Feito para pequenos ouvidos. E grandes corações.</p>`;
if(page==='sleep'&&!query)return `<div class="page-intro"><h1>Boa noite, pequeno coração.</h1><p>Um último abraço em forma de história.</p></div>${hero(stories[2],true)}<section class="parent-panel"><h2>Vamos preparar o soninho?</h2><p>Diminua a luz, encontre uma posição gostosa e respire bem devagar. Agora é só ouvir.</p><div class="settings-row"><div><strong>Hora de descansar</strong><small>O áudio pausa quando o tempo terminar.</small></div>${timerSelect()}</div></section>`;
let list=stories.filter(s=>(page!=='favorites'||favorites.includes(s.id))&&(filter==='Todas'||s.category===filter)&&`${s.title} ${s.subtitle} ${s.category}`.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(query.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()));return `<div class="page-intro"><h1>${page==='favorites'?'Histórias guardadas no coração':query?'Encontre sua próxima história':'Toda história é uma descoberta.'}</h1><p>${page==='favorites'?'Aquelas que a gente quer ouvir mais uma vez.':'Escolha uma capa. A aventura começa no play.'}</p></div>${chips()}<div class="cards">${list.length?list.map(card).join(''):`<div class="empty">${icon(page==='favorites'?'heart':'search')}<h3>${page==='favorites'?'Seu coração tem espaço para histórias.':'Ainda não encontramos essa história.'}</h3><p>${page==='favorites'?'Toque no coração do player para guardar suas preferidas aqui.':'Experimente outro nome ou escolha uma categoria.'}</p><button class="primary" data-page="library">Explorar histórias</button></div>`}</div>`}
function timerSelect(){return `<select aria-label="Temporizador de descanso" data-timer>${[0,5,10,15,30].map(n=>`<option value="${n}" ${timerMinutes===n?'selected':''}>${n?n+' minutos':'Desativado'}</option>`).join('')}</select>`}
function favoriteButton(){return `<button class="icon-btn favorite ${favorites.includes(current.id)?'fav-on':''}" data-favorite aria-label="${favorites.includes(current.id)?'Remover dos favoritos':'Adicionar aos favoritos'}" aria-pressed="${favorites.includes(current.id)}">${icon('heart')}</button>`}
function mini(){return `<section class="mini" aria-label="Player de áudio"><button class="mini-info" data-open-player aria-label="Abrir player"><img src="${asset(current)}" alt=""><span><strong>${current.title}</strong><small>Narração demonstrativa</small></span></button><div class="mini-center"><div class="controls"><button class="icon-btn" data-skip="-15" aria-label="Voltar 15 segundos">${icon('back')}</button><button class="round-play" data-toggle aria-label="Reproduzir">${icon(audio.paused?'play':'pause')}</button><button class="icon-btn" data-skip="15" aria-label="Avançar 15 segundos">${icon('next')}</button></div><div class="mini-range"><span data-elapsed>${fmt(audio.currentTime)}</span><input data-seek type="range" min="0" max="100" value="0" aria-label="Posição do áudio"><span data-duration>${fmt(audio.duration)}</span></div></div><div class="mini-right">${favoriteButton()}${icon('volume')}<input type="range" data-volume min="0" max="1" step=".05" value="${audio.volume}" aria-label="Volume"><button class="icon-btn" data-open-player aria-label="Expandir player">${icon('expand')}</button></div></section>`}
function render(){document.documentElement.dataset.theme=theme;app.innerHTML=`${nav()}<main class="main ${page==='sleep'?'night-mode':''}"><header class="topbar"><div class="hello"><strong>Olá, que bom ter você aqui!</strong>Vamos cultivar coisas boas?</div><div class="brand mobile-brand">${icon('sprout')}sementinha</div><div class="top-actions">${themeButton()}<label class="search">${icon('search')}<input id="search" type="search" placeholder="Buscar uma história" aria-label="Buscar uma história"></label><button class="avatar" data-page="parents" aria-label="Abrir espaço dos pais">S</button></div></header><div id="content">${content()}</div></main>${mini()}<dialog class="player-dialog" id="player"></dialog>`;document.getElementById('search').value=query;sync()}
function openPlayer(){const d=document.getElementById('player');d.innerHTML=`<button class="icon-btn close-player" data-close-player aria-label="Fechar player">${icon('close')}</button><div class="player-layout">${animatedScene()}<div class="player-content"><div class="listening-label"><span class="live-dot"></span><span data-playing-label>Uma pausa para imaginar</span></div><div class="eyebrow">${icon('book')}${current.ref}</div><h2>${current.title}</h2><p>${current.description}</p><div class="player-progress"><input data-seek type="range" min="0" max="100" step=".1" value="0" aria-label="Posição do áudio"><div class="times"><span data-elapsed>${fmt(audio.currentTime)}</span><span data-duration>${fmt(audio.duration)}</span></div></div><div class="controls full-controls"><button class="skip" data-skip="-15" aria-label="Voltar 15 segundos">${icon('back')}15</button><button class="round-play" data-toggle aria-label="Reproduzir">${icon(audio.paused?'play':'pause')}</button><button class="skip" data-skip="15" aria-label="Avançar 15 segundos">${icon('next')}15</button></div><div class="player-options"><button data-speed aria-label="Alterar velocidade">${speed}×</button>${timerSelect()}${favoriteButton()}</div><div class="player-journey-note">${icon('sprout')}Ouça a história para cultivar sua jornada.</div><p class="demo-note">Narração demonstrativa</p></div></div>`;d.showModal();sync()}
async function play(){try{if(!isUnlocked(current.id)){current=stories[journeyCount()]||stories[0];audio.src=`/assets/${current.id}.m4a`;render();openPlayer()}await audio.play()}catch{toast('Não foi possível tocar o áudio. Toque em play para tentar novamente.')}}
function sync(){document.body.classList.toggle('is-playing',!audio.paused);document.querySelectorAll('[data-playing-label]').forEach(e=>e.textContent=audio.paused?'Uma pausa para imaginar':'Deixe a história te levar');document.querySelectorAll('[data-toggle]').forEach(b=>{b.innerHTML=icon(audio.paused?'play':'pause');b.setAttribute('aria-label',audio.paused?'Reproduzir':'Pausar')});document.querySelectorAll('[data-elapsed]').forEach(e=>e.textContent=fmt(audio.currentTime));document.querySelectorAll('[data-duration]').forEach(e=>e.textContent=fmt(audio.duration));document.querySelectorAll('[data-seek]').forEach(e=>{e.value=audio.duration?audio.currentTime/audio.duration*100:0;e.disabled=!Number.isFinite(audio.duration);e.setAttribute('aria-valuetext',`${fmt(audio.currentTime)} de ${fmt(audio.duration)}`)})}
app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-theme')){theme=theme==='dark'?'light':'dark';save('sementinha-theme',theme);document.documentElement.dataset.theme=theme;document.querySelectorAll('[data-theme]').forEach(x=>{x.innerHTML=icon(theme==='dark'?'sun':'moon');x.setAttribute('aria-label',theme==='dark'?'Ativar tema claro':'Ativar tema escuro')});return}if(b.dataset.month){monthOffset+=Number(b.dataset.month);document.getElementById('content').innerHTML=content();return}if(b.hasAttribute('data-next-stage')){document.getElementById('player').close();startStory(stories[Math.min(journeyCount(),stories.length-1)].id);return}if(b.dataset.page){page=b.dataset.page;filter='Todas';query='';render();window.scrollTo({top:0,behavior:'instant'})}else if(b.dataset.filter){filter=b.dataset.filter;document.getElementById('content').innerHTML=content()}else if(b.dataset.story){startStory(b.dataset.story)}else if(b.hasAttribute('data-toggle')){audio.paused?play():audio.pause()}else if(b.dataset.skip){if(Number.isFinite(audio.duration))audio.currentTime=Math.max(0,Math.min(audio.duration,audio.currentTime+Number(b.dataset.skip)))}else if(b.hasAttribute('data-open-player'))openPlayer();else if(b.hasAttribute('data-close-player'))document.getElementById('player').close();else if(b.hasAttribute('data-favorite')){const liked=favorites.includes(current.id);favorites=liked?favorites.filter(x=>x!==current.id):[...favorites,current.id];save('sementinha-favorites',favorites);document.querySelectorAll('[data-favorite]').forEach(x=>{x.classList.toggle('fav-on',!liked);x.setAttribute('aria-pressed',!liked);x.setAttribute('aria-label',liked?'Adicionar aos favoritos':'Remover dos favoritos')});if(page==='favorites')document.getElementById('content').innerHTML=content();toast(liked?'História removida das favoritas.':'Guardada com carinho nas favoritas.')}else if(b.hasAttribute('data-speed')){speed=({1:1.25,1.25:1.5,1.5:.75,.75:1})[speed];audio.playbackRate=speed;b.textContent=`${speed}×`}});
app.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;document.getElementById('content').innerHTML=content()}if(e.target.hasAttribute('data-seek')&&Number.isFinite(audio.duration))audio.currentTime=audio.duration*Number(e.target.value)/100;if(e.target.hasAttribute('data-volume'))audio.volume=Number(e.target.value)});
app.addEventListener('change',e=>{if(e.target.hasAttribute('data-timer')){clearTimeout(timer);timerMinutes=Number(e.target.value);document.querySelectorAll('[data-timer]').forEach(x=>x.value=timerMinutes);if(timerMinutes){timer=setTimeout(()=>{audio.pause();timerMinutes=0;document.querySelectorAll('[data-timer]').forEach(x=>x.value=0);toast('É hora de descansar. Boa noite!')},timerMinutes*60000);toast(`O áudio vai pausar em ${timerMinutes} minutos.`)}else toast('Temporizador desativado.')}});
['timeupdate','loadedmetadata','play','pause','ended','durationchange'].forEach(x=>audio.addEventListener(x,sync));audio.addEventListener('error',()=>toast('O áudio não carregou. Tente novamente.'));

let theme=read('sementinha-theme',window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');
let journeyData=read('sementinha-journey',{completed:[],days:{},coverage:{}});if(!journeyData||!Array.isArray(journeyData.completed)||!journeyData.days||!journeyData.coverage)journeyData={completed:[],days:{},coverage:{}};
let monthOffset=0,lastAudioPosition=0,lastSaveAt=0;
const stageNames=['O vale da confiança','A colina da coragem','O lago da paz','O arco da esperança','O campo do cuidado','O céu da gratidão'];
const stagePositions=[[18,70],[31,40],[46,64],[59,32],[75,51],[86,23]];
function dateKey(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function journeyCount(){let n=0;for(const s of stories){if(!journeyData.completed.includes(s.id))break;n++}return n}
function isUnlocked(id){return stories.findIndex(s=>s.id===id)<=journeyCount()}
function themeButton(){return `<button class="icon-btn theme-toggle" data-theme aria-label="${theme==='dark'?'Ativar tema claro':'Ativar tema escuro'}">${icon(theme==='dark'?'sun':'moon')}</button>`}
function startStory(id){const next=stories.find(s=>s.id===id);if(!next)return;if(!isUnlocked(id)){toast('Uma descoberta de cada vez. Ouça a etapa anterior para abrir este caminho.');return}if(current.id!==next.id){current=next;audio.src=`/assets/${current.id}.m4a`;audio.playbackRate=speed;lastAudioPosition=0;save('sementinha-last',current.id);render()}openPlayer();play()}
function weekStrip(){const now=new Date(),day=now.getDay();return `<div class="week-strip">${Array.from({length:7},(_,i)=>{const d=new Date(now);d.setDate(now.getDate()-((day+6)%7)+i);const key=dateKey(d),done=(journeyData.days[key]||0)>=15;return `<div class="week-day ${done?'listened':''} ${key===dateKey()?'today':''}" title="${d.toLocaleDateString('pt-BR')}${done?' · ouviu histórias':''}"><span>${['S','T','Q','Q','S','S','D'][i]}</span><b>${done?icon('check'):d.getDate()}</b></div>`}).join('')}</div>`}
function calendar(){const now=new Date(),month=new Date(now.getFullYear(),now.getMonth()+monthOffset,1),count=new Date(month.getFullYear(),month.getMonth()+1,0).getDate(),pad=(month.getDay()+6)%7;return `<section class="calendar"><div class="calendar-heading"><h3>${month.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</h3><div><button class="icon-btn" data-month="-1" aria-label="Mês anterior">‹</button><button class="icon-btn" data-month="1" aria-label="Próximo mês" ${monthOffset>=0?'disabled':''}>›</button></div></div><div class="calendar-grid">${['S','T','Q','Q','S','S','D'].map(t=>`<span class="weekday">${t}</span>`).join('')}${'<span></span>'.repeat(pad)}${Array.from({length:count},(_,i)=>{const d=new Date(month.getFullYear(),month.getMonth(),i+1),k=dateKey(d),done=(journeyData.days[k]||0)>=15;return `<span class="calendar-day ${done?'listened':''} ${k===dateKey()?'today':''}" title="${d.toLocaleDateString('pt-BR')}${done?' · Dia com histórias':''}">${i+1}</span>`}).join('')}</div><p class="calendar-legend"><span></span>Um dia com histórias</p></section>`}
function journey(){const done=journeyCount(),next=stories[Math.min(done,5)],days=Object.values(journeyData.days).filter(x=>x>=15).length;return `<div class="journey-heading"><div><div class="chapter-label">Um pouquinho de fé, todos os dias</div><h1>Seu pequeno<br>grande caminho<span>.</span></h1><p>Cada história é uma descoberta. Vamos juntos?</p></div><div class="week-summary"><span>Seus momentos nesta semana</span>${weekStrip()}</div></div><div class="journey-layout"><section class="journey-world" aria-label="Mapa da jornada, seis etapas"><img class="world-art" src="/assets/journey.jpg" alt="Um jardim de colinas verdes, árvores e um rio azul"><div class="world-top"><span class="world-chapter">${icon('leaf')}Capítulo 1</span><span class="world-progress">${done}/6 descobertas</span></div><div class="world-title"><h2>O Jardim da Fé</h2><p>Onde o amor cria raízes.</p></div><div class="map-route"><svg class="route-lines" viewBox="0 0 1000 650" preserveAspectRatio="none" aria-hidden="true"><path class="route-shadow" d="M180 455 C80 360 230 160 310 260 S385 495 460 416 S490 105 590 208 S685 415 750 332 S940 190 860 150"/><path class="route-path" d="M180 455 C80 360 230 160 310 260 S385 495 460 416 S490 105 590 208 S685 415 750 332 S940 190 860 150"/></svg><svg class="route-lines mobile-route" viewBox="0 0 1000 650" preserveAspectRatio="none" aria-hidden="true"><path class="route-shadow" d="M260 104 C270 45 820 70 690 202 S60 200 300 293 S935 295 710 384 S70 373 280 475 S905 465 690 572"/><path class="route-path" d="M260 104 C270 45 820 70 690 202 S60 200 300 293 S935 295 710 384 S70 373 280 475 S905 465 690 572"/></svg>${stories.map((s,i)=>{const completed=journeyData.completed.includes(s.id),unlocked=isUnlocked(s.id),active=i===done;return `<button class="map-node ${completed?'completed':''} ${active?'current':''} ${!unlocked?'locked':''}" style="--x:${stagePositions[i][0]}%;--y:${stagePositions[i][1]}%" data-story="${s.id}" aria-label="Etapa ${i+1}: ${stageNames[i]}. ${completed?'Concluída':unlocked?'Disponível':'Bloqueada, conclua a anterior'}" aria-disabled="${!unlocked}">${active?'<span class="you-are-here">Sua próxima aventura</span>':''}<span class="node-orbit"><img src="${asset(s)}" alt=""><span class="node-icon">${icon(completed?'check':unlocked?'play':'lock')}</span></span><span class="node-number">${String(i+1).padStart(2,'0')}</span><span class="node-label">${stageNames[i]}</span></button>`}).join('')}</div><div class="world-bottom">${icon('sprout')}Sem pressa. Cada pequeno passo faz florescer.</div></section><aside class="journey-aside"><section class="next-discovery"><span class="chapter-label">${done===6?'Um jardim de descobertas':'Seu próximo passo'}</span><div class="next-cover"><img src="${asset(next)}" alt="">${icon(done===6?'trophy':'play')}</div><h2>${done===6?'Seu jardim floresceu!':next.title}</h2><p>${done===6?'Você conheceu seis histórias de amor. Sempre dá para descobrir algo novo ao ouvir outra vez.':next.description}</p><button class="primary" data-story="${next.id}">${icon(done===6?'back':'play')}${done===6?'Ouvir outra vez':done?'Continuar jornada':'Começar minha jornada'}</button><span class="next-caption">${done===6?'6 histórias para guardar no coração':'Ouça esta história para abrir a próxima etapa.'}</span></section>${calendar()}<div class="gentle-stats">${icon('heart')}<p><strong>${days} ${days===1?'dia':'dias'} com histórias</strong><span>Seu carinho já faz parte deste jardim.</span></p></div></aside></div>`}
function animatedScene(){return `<div class="player-visual scene-${current.id}"><img class="scene-art" src="${asset(current)}" alt="${current.subtitle}"><div class="scene-shade"></div><div class="scene-particles" aria-hidden="true">${Array.from({length:15},(_,i)=>`<span style="--i:${i};--left:${(i*31+9)%95}%;--top:${(i*19+7)%87}%"></span>`).join('')}</div><div class="scene-caption"><span>Sementinha apresenta</span><strong>${current.subtitle}</strong></div><div class="sound-scape" aria-hidden="true">${Array.from({length:29},(_,i)=>`<i style="--i:${i};--bar:${12+(Math.sin(i*.8)+1)*17}px"></i>`).join('')}</div><span class="scene-state" data-scene-state>${icon('volume')}Um mundo para imaginar</span></div>`}
function refreshJourney(){if((page==='journey'||page==='home')&&!query)document.getElementById('content').innerHTML=content()}
function finishStage(){const i=stories.findIndex(s=>s.id===current.id);if(journeyData.completed.includes(current.id)||i!==journeyCount())return;journeyData.completed.push(current.id);save('sementinha-journey',journeyData);refreshJourney();toast(journeyCount()===6?'Seu Jardim da Fé floresceu!':'Uma nova aventura se abriu no seu jardim!');const d=document.getElementById('player');if(d.open){const box=document.createElement('div');box.className='stage-reward';box.setAttribute('role','status');box.innerHTML=`${icon(journeyCount()===6?'trophy':'sprout')}<div><strong>${journeyCount()===6?'Seu jardim floresceu!':'Mais uma sementinha plantada!'}</strong><p>${journeyCount()===6?'As seis descobertas estão no seu coração.':'A próxima descoberta já está esperando por você.'}</p></div><button class="primary" ${journeyCount()===6?'data-page="journey"':'data-next-stage'}>${journeyCount()===6?'Ver meu jardim':'Próxima aventura'}${icon('arrow')}</button>`;d.append(box)}}
audio.addEventListener('seeking',()=>{lastAudioPosition=audio.currentTime});
audio.addEventListener('loadedmetadata',()=>{lastAudioPosition=audio.currentTime});
audio.addEventListener('timeupdate',()=>{const pos=audio.currentTime,delta=pos-lastAudioPosition;lastAudioPosition=pos;if(delta<=0||delta>2.5||audio.seeking||!Number.isFinite(audio.duration))return;const k=dateKey();journeyData.days[k]=(journeyData.days[k]||0)+delta/audio.playbackRate;let coverage=new Set(journeyData.coverage[current.id]||[]);for(let n=Math.floor(pos-delta);n<Math.floor(pos);n++)coverage.add(n);journeyData.coverage[current.id]=[...coverage];if(coverage.size>=Math.floor(audio.duration*.9))finishStage();if(Date.now()-lastSaveAt>5000){save('sementinha-journey',journeyData);lastSaveAt=Date.now();refreshJourney()}});
window.addEventListener('pagehide',()=>save('sementinha-journey',journeyData));
render();
